// Minimal stub of 'ws' for offline logic testing.
// Provides WebSocket.Server as an EventEmitter-like object with .on('connection', cb)
// and a readyState constant, matching what server.js needs without opening real sockets.
const EventEmitter = require('events');

class FakeServer extends EventEmitter {
  constructor(opts) {
    super();
    this.opts = opts || {};
  }
}

function WebSocket() {}
WebSocket.OPEN = 1;
WebSocket.Server = FakeServer;

module.exports = WebSocket;
